//
// Question 1: Text Editor
// Problem Statement
// Implement a prototype for a text editor application that starts with an empty string and the cursor at position 0. Process a 2D array of commands commands[n][2] with the following operations:

// Command	Action
// ["Insert", s]	Insert string s at the current cursor position. The cursor moves right by s.length().
// ["Print", x]	If cursor is at position m, record characters from index max(0,m−x) to min(length,m+x).
// ["Left", x]	Move cursor left by x positions, clamped at index 0.
// ["Right", x]	Move cursor right by x positions, clamped at maximum string length.
// ["Backspace", x]	Delete up to x characters to the left of the cursor.
// ["Delete", x]	Delete up to x characters to the right of the cursor.

//

string s = "";
int curpos = 0;
vector<string> v;
int n = commands.size();
for(int i = 0;i<n;i++){
    if(commands[i][0]=="Insert"){

        s.insert(curpos,commands[i][1]);
        curpos+=commands[i][1].size();


    }

    else if(commands[i][0]=="Print"){


         int x = stoi(commands[i][1]);

        int st = max(0,curpos-x);
        int end = min((int)s.size(),curpos+x);

         v.push_back(s.substr(st,end-st));

    }
    else if(commands[i][0]== "Left"){
        int cnt = max(0,curpos-stoi(commands[i][1]));
        curpos=cnt;
    }
    else if(commands[i][0]== "Right"){
        int cnt = min(s.size(),curpos+stoi(commands[i][1]));
        curpos=cnt;
    }
    else if(commands[i][0]=="Backspace"){
        int cnt = max(0,curpos-stoi(commands[i][1]));
        s.erase(cnt,curpos-cnt);
        curpos=cnt;
    }
    else if(commands[i][0]=="Delete"){
            int cnt = min(stoi(commands[i][1]),(s.size()-curpos));
            s.erase(curpos,cnt);

    }

}

return v;
